<script setup lang="ts">import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue'; import { formatDateOnly } from '@/Support/dateOnly'; import { Head, Link } from '@inertiajs/vue3'; defineProps<{ schoolYear: any; students: any[]; selectedStudent: any; learningPlan: any }>();</script>
